package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// Open failures of type TransientError are retried; any other open error is
// returned. If Frob panics with a FrobError, Defrob is called with the
// FrobError's defrobTag before the resource is closed, and the error is
// returned.
func Use(opener ResourceOpener, input string) (err error) {
	var r Resource
	for {
		r, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}

	// Close exactly once, no matter what happens afterwards.
	defer func() {
		r.Close()
	}()

	// Recover from panics in Frob. This defer is registered after the Close
	// defer, so it runs first (LIFO): Defrob happens before Close.
	defer func() {
		if p := recover(); p != nil {
			if fe, ok := p.(FrobError); ok {
				r.Defrob(fe.defrobTag)
			}
			err = p
		}
	}()

	r.Frob(input)
	return nil
}

